import{_ as t}from"./chunks/7b14bf10707325d435fe.CLk5UyAe.js";import{_ as a}from"./chunks/ac945418977052fbacd6.CObdY42w.js";import{_ as l,C as o,o as i,c as s,j as e,a as n,E as h,a5 as m}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"生活是一场电子游戏，这是你的获胜之道","description":"","frontmatter":{"title":"生活是一场电子游戏，这是你的获胜之道","originalTitle":"Life Is A Video Game, Here’s How You Win","date":"2022-11-26","originalUrl":"https://thedankoe.com/letters/life-is-a-game-heres-how-you-play-it/","minutes":16,"sourceHash":"54ad491d57ae5cf097c4a3384cce802aec1373f936c617efd15ae99946e027c3","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/life-is-a-game-heres-how-you-play-it/"}]]},"headers":[],"relativePath":"letters/life-is-a-game-heres-how-you-play-it.md","filePath":"letters/life-is-a-game-heres-how-you-play-it.md"}'),c={name:"letters/life-is-a-game-heres-how-you-play-it.md"};function f(u,p,d,g,_,k){const r=o("ArticleMeta");return i(),s("div",null,[p[0]||(p[0]=e("h1",{id:"生活是一场电子游戏-这是你的获胜之道",tabindex:"-1"},[n("生活是一场电子游戏，这是你的获胜之道 "),e("a",{class:"header-anchor",href:"#生活是一场电子游戏-这是你的获胜之道","aria-label":'Permalink to "生活是一场电子游戏，这是你的获胜之道"'},"​")],-1)),h(r),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/_VGmzvG7oq4?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>你是否曾体验过绝佳的人类体验？</p><p>你懂的，就是当你发觉自己感到无比自信、充满活力或极其高效时——至少比平时要好得多。</p><p>有人称之为心流（flow）状态。</p><p>在这种意识状态下，除了眼前的事物，其他一切都不重要。</p><p>你会失去那种导致所有精神痛苦的自我意识。</p><p>当你进入这种状态时，你会：</p><ul><li>不再在乎别人的看法</li><li>与你正在参与的任务合二为一</li><li>清楚地知道下一步该做什么、自己做得有多好，并从中获得深深的满足感</li></ul><p>这里的关键，正是神秘主义者、大师和灵性导师们一直试图让你明白的道理。</p><p>痛苦源于比较。</p><p>“自我”是一个想法。它是一个概念。它是<em>存在</em>之后产生的<em>认知</em>。</p><p>它不是一成不变的，但别因此就误以为“自我”不重要。玩游戏的那个角色将决定这个角色能否获胜。</p><p>自我的另一个词是“小我（ego）”。</p><p>当在句子中使用“我”时，它总是出现在比较之前。</p><p>它不是你要摆脱的东西，而是你要发展的东西。</p><p>如果你想减轻痛苦，你必须学会如何控制你的注意力，而注意力受小我的影响很大。</p><p>当你通过注意力产生自我意识，并将自己的某个方面与其他事物进行比较时，你往往会放大这些差异。</p><p>这会消耗你宝贵的精神能量，并往往会让你的思绪变得分散。</p><p>就像当你在镜子里看到皮肤上有一颗痘痘，然后光洁皮肤的<em>想法</em>突然出现在你的意识中时，你就开始滑向消极的心理状态。你在比较你认为它<em>应该</em>是什么样的多个想法，而不是接受事物的现状并继续前行。</p><p>或者，当你把注意力放在你在世界上的地位时，社会成功的<em>想法</em>会在你脑海中浮现，你觉得你“落后”了，而“落后”只是你脑海中的一种信念。</p><p>那么，我们该如何控制我们的注意力呢？</p><p><em>把生活当成一场游戏。</em></p><p>我们这一代人出了名地把对电子游戏的痴迷转移到了商业成功上。</p><p>游戏、商业，以及外部世界（或称矩阵）的其他建构：</p><ol><li>提供令人向往的层级目标</li><li>拥有限制你注意力的结构</li><li>引入挑战以进一步集中你的注意力</li><li>要求玩家具备满足游玩要求的技能</li></ol><p>很少有人明白的是，你可以把生活中的任何情况变成一场游戏。</p><p>如果你能塑造自己的思想去创造一场有趣的游戏，生活就会变得令人愉悦。</p><p>如果你不能，你的思想就会被塑造成去玩社会地位游戏。比如上大学，找一份高薪工作，或者采取另一种结构化的生活方式，以缓解独立自主生活所带来的初期痛苦。</p><p>这封信的目的在于唤醒你的意识。</p><p>我不想让你在20年后醒来时，肩负着更多的责任，却发现自己必须付出双倍的努力才能让生活步入正轨。</p><p>让我们深入探讨。</p><h2 id="宏观与微观游戏" tabindex="-1">宏观与微观游戏 <a class="header-anchor" href="#宏观与微观游戏" aria-label="Permalink to &quot;宏观与微观游戏&quot;">​</a></h2><p>在玩像《魔兽世界》（World Of Warcraft）这样的开放世界策略游戏时，有几个关于它与日常生活的联系的模式值得注意。</p><p>有些很明显的事情，比如：</p><ul><li>攒金币</li><li>选择职业</li><li>提升角色等级</li></ul><p>以及伴随这些事情的进度发展。</p><p>但是，人们往往会忽略一些事情，而它们或许能帮你从全新的视角看待生活。</p><p><strong>游戏是预先编写好并下载到硬盘上的</strong></p><blockquote><p>体系是被操纵的。\\</p><p>你无法改变它。\\</p><p>但你可以学习它。\\</p><p>这就是你如何操纵自己来顺应体系的方式。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1544277416704720898?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">July 5, 2022</a></p></blockquote><p>传统的成功之路已经被编入了大众的集体心理中。</p><p>在我们意识到之前，我们已经开始追求去赢下社会想要我们去玩的这场游戏，而这通常是为了维持这个游戏运转。</p><ul><li>上大学</li><li>找份高薪工作</li><li>在65岁退休，这样你终于能享受生活了</li></ul><p>90%的情况下，事情并不会如愿以偿。</p><p>（而且通常以长期的焦虑、绝望和缺乏成就感而告终）。</p><p>为什么？因为时代在变，而程序员们打补丁的速度不够快。因为那需要他们彻底改革学校、银行和就业系统。</p><p>拆除摩天大楼的一块基石，可能会导致它倒塌。</p><p>这就是为什么个人正在填补这些角色（并借此获得丰厚收入），他们作为创作者（creator）在网上教导他人、编写去中心化货币程序，并作为独立合同工（比如做自由职业）提供服务。</p><p>那些从不质疑这个系统，反而屈服于他们被设定的程序的人，被称为NPC。</p><p>非玩家角色（Non-Player Characters）。</p><p>这些人包括镇民、战斗任务中的首领，以及其他为玩家保持游戏趣味性的角色。他们只是听命行事。</p><p>然后，还有一些人选择带着清醒的意识玩游戏，在玩集体小我创造的这个游戏中享受乐趣。</p><p><strong>你可以选择无限的路径</strong></p><p><img src="'+t+'" alt=""></p><p>在《魔兽世界》中，你可以做出一系列的决定：</p><ul><li>你的角色长什么样</li><li>他们是哪种类型的玩家（战士、法师等）</li><li>他们想学什么专业</li><li>他们想选择哪条任务路线来升级</li><li>他们是单刷还是组队</li><li>他们加入哪个公会来帮助他们更快升级</li></ul><p>以及一系列其他个人选择，让你可以按照自己喜欢的方式玩游戏。</p><p>你看，生活就像一座山，但这座山是无限高的。</p><p>如果有5个人站在山脚下，你让他们各自规划一条通往第一座山峰的路线，所有人画出的路线都会略有不同。</p><p>然后，当他们到达那座山峰时，他们不仅能够俯视并帮助其他人爬得更快，而且还有另一座山峰要去攀登，只是这一次，他们有了先前的经验作为起点。</p><p><strong>提升等级会增加自我的复杂性</strong></p><p>在现实世界中，主要的精神问题是人们从不改变。</p><p>他们认同被灌输给他们的信念、工作和人生轨迹。</p><p>他们的小我从未改变，因为它不想变。</p><p>一旦他们到了人生的那个阶段，他们就不再学习、不再积累技能、不再“升级”去获得更多的机会。</p><p>通过提升你的技能包，你能够应对生活中更复杂的挑战。</p><p>通过应对更多挑战，你获得了扩展你意识的知识和经验。</p><p>就像在电子游戏里，把技能点加到你的技能树中的特定特质上一样。</p><p>最终，你拥有了如此强大的力量和丰富的经验，整个世界都可以任你自由漫游，没有任何压力或负担。</p><p>通过接受更高水平的挑战，地图上曾经的未知区域现在已经被探索出来——而且你可以随心所欲地继续探索。</p><p>随着你的自我发展，你具备了从混乱中建立秩序所必需的知识和经验。</p><p>你拥有了更大的力量，可以从任何情况中创造乐趣。</p><p>这个整体结构代表了人生的游戏，即宏观游戏。</p><p>但是，还有更深的一层。</p><p>你身处的每一个具体情境，都可以被视为一场微观游戏。</p><p>游戏中的游戏。</p><p>让我们讨论一下，在玩人生这场游戏时，你如何创造最大的乐趣。</p><h2 id="设定目标层级" tabindex="-1">设定目标层级 <a class="header-anchor" href="#设定目标层级" aria-label="Permalink to &quot;设定目标层级&quot;">​</a></h2><p>游戏呈现了获胜的大目标。</p><p>它们也提供次级目标，比如任务，引导你赢得游戏。</p><p>如果只有获胜这一个目标，而你对如何获胜毫不知情，那游戏就不好玩了。你的头脑也将无法维持秩序，这意味着它将陷入混乱。</p><p>到了今天，为你的未来创造一个愿景是一件好事，这应该已经是常识了。</p><p>作为人类，我们拥有<em>瞄准</em>的能力。</p><p>猴子会扔自己的粪便，但它们不会提前<em>计划</em>。粪便通常是被直直地甩向地面。</p><p>另一方面，人类能够把注意力集中在一个目标上，并且根据他们的技能水平，能够射中50码外的靶心。</p><p>我们不想做被甩向地面的粪便，所以我们创造了一个可以为之建设的愿景。</p><p>但是，如果我们不想被自己宏大的愿景压垮，我们就需要一个计划。一套自上而下的目标，为我们的日常行动带来清晰度，让这些行动执行起来更加容易。</p><p>大处着眼，小处着手。</p><p>拿上纸和笔坐下来，或者<a href="https://shop.thedankoe.com/planner" target="_blank" rel="noreferrer">使用我的效率手账（Power Planner）</a>，去：</p><ul><li>创建你愿景的第一版迭代</li><li>制定10年、1年和月度目标</li><li>留出一个用于每周方向和反思的地方</li><li>将你的每日优先任务与上述内容对齐</li></ul><p>把这些写下来，你就能拓宽你的意识，去注意到那些能为该愿景提供动力的机会。</p><p>随着脑海中涌现出更好的想法，你可以进一步完善它们，从而让你的头脑井然有序。</p><h2 id="游戏的框架" tabindex="-1">游戏的框架 <a class="header-anchor" href="#游戏的框架" aria-label="Permalink to &quot;游戏的框架&quot;">​</a></h2><p>你的视角就是你感知现实的框架。</p><p>就像一台相机。</p><p>视野范围，哪怕背景是模糊的，也限制了到底什么会被记录在画面中。</p><p>通过在任何情况下操纵你的视角，你可以把过去觉得棘手的问题看作是小小的颠簸。</p><p>在电子游戏中，有两件事能以一种减轻焦虑、不知所措和压力的方式来使意识保持有序。</p><p><strong>1) 规则</strong></p><p>每一个电子游戏都有一套必须遵守的规则，只有这样才能在不作弊的情况下赢得游戏。</p><p>当我们玩游戏时，这让我们能够利用有限的意识注意力，在心里保留最终目标的同时，保持专注于此时此地。</p><p>在心理学中，一想到在未来能拥有某种渴望的东西（即赢得游戏或实现你的愿景），多巴胺就会喷涌进你的大脑。</p><p>而当你欣赏眼前的事物（即玩游戏或执行优先任务）时，“此时此地”的化学物质——如血清素、催产素和内啡肽——会奖励你的大脑。</p><p>因此，只有当你带着获胜的意图去玩游戏时，你才更有可能进入那种令人愉悦的心流（flow）状态，这完全合乎逻辑。</p><p><em>从科学标准来看，心流只不过是充斥在你大脑里的一杯奖赏化学物质鸡尾酒，而它是通过集中的注意力来调动的。</em></p><p>但是，前提是你必须满足我们很快就会讨论到的其他要求。</p><p>在现实世界中，在人生的宏观尺度上，<strong>你的“规则”就是你的价值观。</strong></p><p>你认为重要的那些东西。</p><p>当你的行动与你的价值观保持一致，同时将这些行动约束在有利于你人生目标的轨道上时，极致的乐趣便会随之而来。</p><p>在日常情境的微观尺度上，清晰度来自于消除环境中的干扰。</p><p>就像当你努力进行深度工作（deep work）时。</p><p>你会关闭浏览器标签页，戴上降噪耳机，并且为你的工作制定明确的步骤。</p><p>当这份工作与内在结果相一致时，你能猜到接下来会发生什么。心流。</p><p>现在，这不仅归结于理解并消除环境中的干扰。</p><p>你可以在过去那些枯燥乏味的场景中制定规则或界限。</p><p>我曾经很讨厌去长途散步，即使我知道那对我的身心健康有益。</p><p>所以，你可以这样做：</p><ul><li>为这个场景设定一个目标，比如走2500步</li><li>制定规则让它游戏化，比如绝对不踩到地砖缝隙</li><li>采取阻力最小的行动，比如先迈出你家的大门</li></ul><p><em>目标，清晰，简化的行动。</em></p><p>这同样适用于你平时极其讨厌的场景。</p><p>比如，如果你不“理解”为什么人们喜欢看体育比赛或去观鸟。</p><p><em>从中创造你自己的游戏。</em></p><p><strong>2) 操作机制</strong></p><p>如果你以前没玩过这个游戏，那将会很困难。</p><p>你的瞄准会烂透了。</p><p>你必须在低级别的挑战中进行练习。</p><p>你会被顶级玩家精湛的技艺所震撼。</p><p>每一个游戏都有一种特定的方式，让你将更多的感官、思想和过往经验融入其中，并通过注意力加以引导。</p><p><strong>在电子游戏中</strong>，它是按下一系列键盘、按钮或点击鼠标。</p><p><strong>在棋盘游戏中</strong>，它是融入你策略中的有效性、创造力或前瞻性思维。</p><p><strong>在体育运动中</strong>，它是对身体的调理，以及你如何为了达成目标而移动身体。</p><p>在以上所有情况中，这都关乎你对局势的感知（游戏的框架）以及你为了获胜而选择的行动方式。</p><p>在这里，反馈至关重要。</p><p>游戏在进行时，需要一种方法来维持秩序。</p><p>当你知道自己表现得如何时，你就不太可能分散注意力。</p><p>如果你的视角受限，无法以一种让你获得清晰感的方式感知局势，你就很难走出一招“好棋”并最终获胜。</p><p>当这种情况发生时，你的大脑会拓宽其视角——或者说框架化注意力——这便给分心留下了空间。</p><p>我们如何在玩游戏时改善我们的操作机制？</p><p>当然是靠练习。</p><p>在游戏中，你通常每天登录去执行重复性的任务流程。比如肝任务、刷经验，或者为了提升职业等级去打造武器。</p><p>你必须将那个特定的操作机制编程到你的大脑中，让它变得毫不费力。</p><p>换句话说，就是习惯的养成。</p><p>如果你能将你所做的决定自动化，成功就会变得毫不费力。</p><p>这需要时间，以及对学习永无止境的渴望。</p><p>我们稍后会详细讨论这一点。</p><h2 id="焦虑与无聊的微妙平衡" tabindex="-1">焦虑与无聊的微妙平衡 <a class="header-anchor" href="#焦虑与无聊的微妙平衡" aria-label="Permalink to &quot;焦虑与无聊的微妙平衡&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>当你开始玩一个游戏，尤其是在没有阅读规则手册的情况下，这种体验会令人愉悦吗？</p><p>也许不会。</p><p>即使你知道了规则，在你开始掌握游戏的操作机制之前，它也不会那么令人愉悦。</p><p>如果你在《魔兽世界》中只有1级，并且<em>不知怎么地</em>能与一个50级的角色战斗，这会好玩吗？</p><p>第一，你会立刻落败。</p><p>第二，不，这根本不好玩，除非你在脑海中为这个游戏创建了一个更好的框架——比如你就是想输，因为你想看看50级到底有多强。</p><p>如果你只是和哥们儿下过几次国际象棋，你会考虑去参加竞技比赛吗？或者去挑战国际象棋特级大师？</p><p>经验教训：</p><p>如果你的技能与游戏所呈现的挑战不匹配，你就会有糟糕的体验。</p><p>如果你的技能很高而挑战很低，你会感到无聊。</p><p>如果你的技能很低而挑战很高，你会感到焦虑。</p><p><strong>无聊</strong>源于自我中心。你的注意力分散了，一个新欲望突然蹦进你的脑海，相关的想法开始占据你的注意力。</p><p>如果你在工作中感到无聊，你就会开始想自己原本可以去做哪些更具生产力的事情。</p><p><strong>焦虑</strong>源于自我意识。你的焦点转向了你的自我概念，同样的，相关的想法开始渗透进你的意识场。</p><p><em>“哇，我并没有自己想象的那么好。”</em></p><p><em>“我真的需要改进我的上杆动作了。”</em></p><p><em>“那个女孩我根本高攀不上。”</em></p><p>注意“我”和“我的”的使用，这暗示了一种比较。</p><p>这种比较会导致精神熵：<a href="https://thedankoe.com/the-cure-to-caring-what-people-think/" target="_blank" rel="noreferrer">大脑倾向于走向无序，除非有适当的能量来维持</a>，也就是那些可以被意识处理为能量的有序信息。</p><p>我们该如何防止这种情况？</p><p>通过终身学习。</p><p>如果你读这封订阅信已经有一段时间了，你就会知道这意味着什么：</p><p><a href="https://thedankoe.com/how-i-remember-everything-i-learn/" target="_blank" rel="noreferrer">终身构建。</a></p><p>从这个角度来看，不仅要把你的生活看作一场游戏，更要把它看作一个项目。</p><p>在你的脑海中抱有改进的意图，当遇到引发焦虑或无聊的问题时，通过学习特定的知识来克服那个问题。</p><h2 id="别讨厌玩家-去创造玩家" tabindex="-1">别讨厌玩家，去创造玩家 <a class="header-anchor" href="#别讨厌玩家-去创造玩家" aria-label="Permalink to &quot;别讨厌玩家，去创造玩家&quot;">​</a></h2><blockquote><p>在我们历史的这个阶段，一个人应该有可能构建出一个不单纯是生物本能和文化习惯产物的自我，而是一个有意识的、个人的创造物。——米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）</p></blockquote><p>我记得我十几岁时第一次下载《魔兽世界》的情景。</p><p>我足足花了两个小时研究每个种族、职业的细节，以及改变外貌的选项，同时脑海中始终抱有获胜的念头，以此来做出正确的决定。</p><p>我是要当战士？萨满？还是介于两者之间的职业？</p><p>我想当巨魔吗？</p><p>也许只是个留长发的人类？</p><p>当我去挑战某些任务和副本时，我的性格最适合当坦克、辅助还是输出角色？</p><p>当我升到15级时又该怎样？</p><p>我想追求什么生活技能？</p><p>有很多像炼金术、采矿、锻造等技能，这将决定我能在多大程度上利用公共贸易系统。</p><p>一旦做出了选择，我就拥有了一系列可以随着经验值升级的“天赋”和“特质”。</p><p>而当我把它们升到特定水平时，我就能获得更多原本无法解锁的选项。</p><p>追忆就到此为止，这如何应用于日常生活中呢？</p><p>首先，为了给你描绘一幅清晰的画面，我不认为人性本善。</p><p>就像夏娃吃下智慧树上的苹果一样，我们拥有想要了解更多知识的无尽欲望。</p><p>学习是人类体验的基础。</p><p>当我们年轻时，我们什么都不懂，最终得到一个被编程进我们大脑的“自我”。这个自我是从我们的环境中习得的。</p><p>通过任何媒介进行的学习，都会影响我们的思想。尤其是当我们所学的东西被重复或条件反射式地灌输进大脑时。</p><p>我们的思想影响行为。</p><p>这意味着，你学习或消费的任何东西，都在塑造你是谁以及你在这个世界上如何行动。</p><p>赢得生活、商业或你当前所处任何局势的游戏，取决于你的角色在那个游戏中如何去框架、感知并采取行动。</p><p>成功是我们脑海中抱有的一个主观目标。</p><p>目标的实现是通过一系列正确的行动来完成的。</p><p>所以，如果我们想实现梦想中的生活，我们必须创造一个能把生活这场游戏玩得溜的角色。</p><p>我们该如何创造我们的角色？</p><p><strong>1) 通过整合我们在本期订阅信中讨论过的一切。</strong></p><p>在任何给定时刻，你都需要一个内在的目标层级来理顺你的大脑。</p><p>当你迷失时，把注意力集中在你的愿景、目标和优先事项上，以此获得清晰感。</p><p><strong>2) 通过自我教育和自我反思。</strong></p><p>你的目标层级会呈现出一系列的挑战，你必须通过技能获取、解决问题和直接经验去应对这些挑战。</p><p>这些都是学习的形式。</p><p>值得庆幸的是，我们生活在一个任何信息都触手可及的时代。你问题的解决方案，就存在于那些你必须去付诸实践的理念之中。</p><p>你通过持续消费有价值的信息来发现这些理念。有时你不得不在沙土里淘金。这是一个终生的过程，唯有分心和廉价的快感才能将其阻断。</p><p>自我反思是你指导未来决策的方式。</p><p>怎么做？</p><p>因为你不可能对自己采取的行动有100%的确定性。</p><p>你就是必须去采取行动。</p><p>当你这么做之后，你唯一能判断这些行动好坏的方法，就是通过自我反思。</p><p>如果你现在的生活是你过去决定的产物，那就意味着，除非事情发生，否则你无法预知某个“因”会产生什么“果”。</p><p>即使因为有人告诉过你，你“知道”会发生什么，你也没有考虑到其他每一个可能导致不同结果的环境因素。没有直接经验，你就限制了自己的潜力。</p><p>当你坐下来仔细思考你的决定时，那就是你发现“果”的方式。</p><p>由此，随着时间的推移，你的决定会变得越来越准确，直到你达成目标。</p><p>让我们做一个快速总结：</p><ul><li>游戏是一种将意识排序到痴迷程度的方法。</li><li>当你沉迷其中时，你就不再关心别人的看法，而是根据你的价值观去为了获胜而玩。</li><li>游戏是令人愉悦的，生活中的每一个场景都可以在精神上被塑造成一场游戏。</li><li>如果你想避免精神混乱，你的技能必须与任何场景带来的挑战相匹配。</li><li>你的视角将决定你所能获取的信息，如果信息缺乏结构，你就会产生误解。</li><li>你的自我（一个概念），就是玩家。随着时间的推移，你要创造出那个能在自己最擅长的游戏中获胜的角色。</li></ul><p>希望大家喜欢阅读这篇文章。这是我最喜欢写的文章之一。</p><p>开始玩这场大型游戏吧，我的朋友们。</p><p>——<em>Dan Koe</em></p><p><strong>本周动态</strong></p><p>《两小时写作者》（The 2-Hour Writer）正在黑五网一（BFCM）周末促销。如果你想学习一项加入数字（及/或创作者）经济的基础技能，你可以享受七折优惠。</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">了解《两小时写作者》。</a></p><p>在Modern Mastery（现代精通）中，发布了2个策略。一个是7个推文模板以及对爆款推特长文结构的拆解。另一个是我如何想出够用3年的内容创意，以此将我和其他所有创作者区分开来。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者只需5美元即可加入。</a></p><p>在YouTube上，我发布了“矩阵是真实的（这是你用心智逃脱的方法）”。另一期关于我如何记住我所学一切的视频将于明天发布。</p><p><a href="https://youtube.com/c/DanKoeTalks" target="_blank" rel="noreferrer">在此订阅观看。</a></p><p><em>一如既往，当你准备好时，你可以<a href="https://thedankoe.com/" target="_blank" rel="noreferrer">在我的网站上</a>找到我其他免费和付费的产品，用于改善你的生活和业务。</em></p><hr><p><a href="/en/letters/life-is-a-game-heres-how-you-play-it">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',229))])}const P=l(c,[["render",f]]);export{q as __pageData,P as default};
